#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> last_pos(100001, -1);
    int max_len = 0;
    int left = 0;

    for (int right = 0; right < n; ++right) {
        int val;
        cin >> val;
        if (last_pos[val] >= left) {
            left = last_pos[val] + 1;
        }
        last_pos[val] = right;
        max_len = max(max_len, right - left + 1);
    }

    cout << max_len << "\n";

    return 0;
}
